create or replace function public.get_loan_servicing_policy()
returns table(minimum_restructure_term_months integer,maximum_restructure_term_months integer,restructure_requires_maker_checker boolean,write_off_requires_maker_checker boolean,settlement_quote_validity_days integer,settlement_rebate_method text)
language sql stable security definer set search_path=public,pg_temp as $$ select minimum_restructure_term_months,maximum_restructure_term_months,restructure_requires_maker_checker,write_off_requires_maker_checker,settlement_quote_validity_days,settlement_rebate_method from public.loan_servicing_policies where institution_id=public.current_institution_id() and public.has_permission('servicing.manage') $$;
create or replace function public.save_loan_servicing_policy(p_min integer,p_max integer,p_restructure_dual boolean,p_writeoff_dual boolean,p_quote_days integer,p_rebate_method text)
returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.has_permission('servicing.manage') or p_min<1 or p_max<p_min or p_quote_days<1 or p_quote_days>90 or p_rebate_method not in('policy_required','none') then raise exception 'invalid policy or permission denied'; end if; update public.loan_servicing_policies set minimum_restructure_term_months=p_min,maximum_restructure_term_months=p_max,restructure_requires_maker_checker=p_restructure_dual,write_off_requires_maker_checker=p_writeoff_dual,settlement_quote_validity_days=p_quote_days,settlement_rebate_method=p_rebate_method,updated_by=auth.uid(),updated_at=now() where institution_id=public.current_institution_id(); end $$;
create or replace function public.assign_staff_collection_case(p_loan_account_id uuid,p_staff_profile_id uuid)
returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare inst uuid:=public.current_institution_id(); cid uuid; begin if not public.has_permission('collections.manage') then raise exception 'permission denied'; end if; if not exists(select 1 from public.staff_members where profile_id=p_staff_profile_id and institution_id=inst and is_active) then raise exception 'active staff member unavailable'; end if; select id into cid from public.collection_cases where institution_id=inst and loan_account_id=p_loan_account_id and status in('open','paused') order by opened_at desc limit 1 for update; if cid is null then insert into public.collection_cases(institution_id,loan_account_id,assigned_staff_profile_id,status) values(inst,p_loan_account_id,p_staff_profile_id,'open') returning id into cid; else update public.collection_cases set assigned_staff_profile_id=p_staff_profile_id where id=cid; end if; insert into public.audit_events(institution_id,actor_profile_id,action,target_type,target_id,after_state) values(inst,auth.uid(),'COLLECTION_CASE_ASSIGNED','collection_case',cid,jsonb_build_object('assigned_staff_profile_id',p_staff_profile_id)); end $$;
revoke all on function public.get_loan_servicing_policy(),public.save_loan_servicing_policy(integer,integer,boolean,boolean,integer,text),public.assign_staff_collection_case(uuid,uuid) from public;
grant execute on function public.get_loan_servicing_policy(),public.save_loan_servicing_policy(integer,integer,boolean,boolean,integer,text),public.assign_staff_collection_case(uuid,uuid) to authenticated;
